if ($_SERVER['REQUEST_METHOD']==='POST' && hash_equals($_SESSION['csrf'], $_POST['_csrf']??'')) { $id=(int)$_POST['id']; $action=$_POST['action']??''; if($action==='delete')$conn->query("DELETE FROM topics WHERE id=$id"); elseif($action==='lock')$conn->query("UPDATE topics SET is_locked=1 WHERE id=$id"); elseif($action==='unlock')$conn->query("UPDATE topics SET is_locked=0 WHERE id=$id"); }
$topics=$conn->query('SELECT t.id,t.title,t.is_locked,t.is_pinned,t.created_at,u.username,c.name category_name FROM topics t JOIN users u ON u.id=t.user_id JOIN categories c ON c.id=t.category_id ORDER BY t.created_at DESC');
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contenido · Nexo Admin</title><link rel="stylesheet" href="../assets/css/nexo.css"><link rel="stylesheet" href="admin.css"></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">N</span><span>NEXO ADMIN</span></a><nav><a href="index.php">Dashboard</a><a href="users.php">Usuarios</a><a href="categories.php">Categorías</a><a href="reports.php">Reportes</a></nav></header><main class="admin-shell"><div class="admin-heading"><span class="eyebrow">MODERACIÓN</span><h1>Contenido</h1></div><div class="admin-card"><div class="admin-table"><div class="table-row table-head"><span>Tema</span><span>Autor / categoría</span><span>Acciones</span></div><?php while($t=$topics->fetch_assoc()): ?><div class="table-row"><span><b><?=e($t['title'])?></b><small><?=e($t['created_at'])?></small></span><span><?=e($t['username'])?><small><?=e($t['category_name'])?></small></span><span class="actions"><a class="mini-button" href="../topic.php?id=<?=$t['id']?>">Ver</a><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$t['id']?>"><button name="action" value="<?=$t['is_locked']?'unlock':'lock'?>" class="mini-button"><?=$t['is_locked']?'Abrir':'Cerrar'?></button><button name="action" value="delete" class="mini-button danger">Borrar</button></form></span></div><?php endwhile; ?></div></div></main></body></html>